package mz.bam.seeky.android;
import android.content.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;

/** Journal transfers before touching staged files. Large books move; small editable JSONs copy. */
final class BackupTransfers {
    final Map<String,String> paths=new LinkedHashMap<>(),moved=new LinkedHashMap<>();final List<File> created=new ArrayList<>();final List<File[]> copies=new ArrayList<>();
    BackupTransfers(Context c,WorkspaceBackup.Staged staged)throws Exception{JSONArray rows=staged.manifest.getJSONArray("entries");for(int i=0;i<rows.length();i++){JSONObject item=rows.getJSONObject(i);if(!item.getString("kind").equals("file"))continue;String old=item.getString("path"),folder=item.getString("folder");if(!BackupExtras.FOLDERS.contains(folder))throw new IOException("Pasta de ficheiro incompatível.");if(staged.local&&!item.optBoolean("snapshot")){paths.put(old,WorkspaceBackup.privateFile(c,old).getPath());continue;}File root=new File(c.getFilesDir(),folder);root.mkdirs();String extension=folder.equals("voice-notes")?"wav":StudyFiles.extension(new File(old).getName());File target=new File(root,"restore-"+UUID.randomUUID()+"."+extension),source=staged.entries.get(item.getString("entry"));if(source==null)throw new IOException("Falta uma parte da cópia.");created.add(target);paths.put(old,target.getPath());if(BackupExtras.mutable(old))copies.add(new File[]{source,target});else moved.put(source.getPath(),target.getPath());}}
    void apply(java.util.function.BooleanSupplier cancelled)throws Exception{for(File[] pair:copies){WorkspaceBackup.check(cancelled);Files.copy(pair[0].toPath(),pair[1].toPath());}for(Map.Entry<String,String> pair:moved.entrySet()){WorkspaceBackup.check(cancelled);Files.move(new File(pair.getKey()).toPath(),new File(pair.getValue()).toPath());}}
    void rollback(Context c)throws Exception{undo(c,new JSONObject(moved));for(File file:created)if(file.exists())Files.delete(file.toPath());}
    static void undo(Context c,JSONObject moved)throws Exception{if(moved==null)return;Iterator<String> keys=moved.keys();while(keys.hasNext()){String key=keys.next();File source=new File(key).getCanonicalFile();File target=new File(moved.getString(key)).getCanonicalFile();if(!DiskWalker.inside(c.getCacheDir().getCanonicalFile(),source)||!source.getParentFile().getName().startsWith("workspace-restore-")||!DiskWalker.inside(c.getFilesDir().getCanonicalFile(),target)||!target.getName().startsWith("restore-"))throw new IOException("Transferência pendente inválida.");if(!source.exists()&&target.isFile())Files.move(target.toPath(),source.toPath());}}
}
